// ─── Icon Rendering ───
function renderIconSvg(IconComponent, color, size) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// ─── Helpers ───
function makeShadow() {
  return { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.08 };
}

function addFooter(pres, slide, slideNum) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.325, w: 10, h: 0.3,
    fill: { color: C.lightBg }
  });
  slide.addText(`Source: Our World in Data – Renewable Energy (2025)`, {
    x: 0.5, y: 5.325, w: 7, h: 0.3,
    fontSize: 8, fontFace: "Calibri", color: C.textMuted, valign: "middle"
  });
  slide.addText(`${slideNum} / 9`, {
    x: 8.5, y: 5.325, w: 1, h: 0.3,
    fontSize: 8, fontFace: "Calibri", color: C.textMuted, valign: "middle", align: "right"
  });
}

function addFooterDark(pres, slide, slideNum) {
