const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const path = require("path");

// ─── Color Palette (Forest & Energy) ───
const C = {
  darkBg: "0B3D2E",
  darkBgAlt: "0A3326",
  primary: "0F7B5F",
  secondary: "2EC4A0",
  accent: "E8A838",
  accentRed: "D94F4F",
  lightBg: "F7F5F0",
  cardBg: "FFFFFF",
  textDark: "1C2B33",
  textMuted: "5A6B74",
  textLight: "FFFFFF",
  border: "D4DDD7",
  tableHeader: "0F7B5F",
  tableAlt: "EEF5F1",
};

const FIGURES_DIR = path.join(__dirname, "benchmark", "assets");
const OUTPUT_PATH = path.join(__dirname, "output", "final_deck.pptx");

// ─── Icon Rendering ───
function renderIconSvg(IconComponent, color, size) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// ─── Helpers ───
function makeShadow() {
  return { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.08 };
}

function addFooter(pres, slide, slideNum) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.325, w: 10, h: 0.3,
    fill: { color: C.lightBg }
  });
  slide.addText(`Source: Our World in Data – Renewable Energy (2025)`, {
    x: 0.5, y: 5.325, w: 7, h: 0.3,
    fontSize: 8, fontFace: "Calibri", color: C.textMuted, valign: "middle"
  });
  slide.addText(`${slideNum} / 9`, {
    x: 8.5, y: 5.325, w: 1, h: 0.3,
    fontSize: 8, fontFace: "Calibri", color: C.textMuted, valign: "middle", align: "right"
  });
}

function addFooterDark(pres, slide, slideNum) {
  slide.addText(`Source: Our World in Data – Renewable Energy (2025)`, {
    x: 0.5, y: 5.325, w: 7, h: 0.3,
    fontSize: 8, fontFace: "Calibri", color: "8FA89A", valign: "middle"
  });
  slide.addText(`${slideNum} / 9`, {
    x: 8.5, y: 5.325, w: 1, h: 0.3,
    fontSize: 8, fontFace: "Calibri", color: "8FA89A", valign: "middle", align: "right"
  });
}

// ─── Main ───
async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Our World in Data";
  pres.title = "Global Renewable Energy in 2025: How Far Have We Come?";

  // Load icons
  const { FaIndustry, FaSmog, FaBolt, FaWater, FaWind, FaSun, FaGlobeAmericas, FaExclamationTriangle, FaArrowRight, FaChartLine, FaFlag, FaLeaf } = require("react-icons/fa");

  const iconIndustry = await iconToBase64Png(FaIndustry, "#E8A838", 256);
  const iconSmog = await iconToBase64Png(FaSmog, "#D94F4F", 256);
  const iconExclamation = await iconToBase64Png(FaExclamationTriangle, "#E8A838", 256);
  const iconBolt = await iconToBase64Png(FaBolt, "#2EC4A0", 256);
  const iconWater = await iconToBase64Png(FaWater, "#3B8DB8", 256);
  const iconWind = await iconToBase64Png(FaWind, "#2EC4A0", 256);
  const iconSun = await iconToBase64Png(FaSun, "#E8A838", 256);
  const iconGlobe = await iconToBase64Png(FaGlobeAmericas, "#0F7B5F", 256);
  const iconChart = await iconToBase64Png(FaChartLine, "#2EC4A0", 256);
  const iconFlag = await iconToBase64Png(FaFlag, "#D94F4F", 256);
  const iconLeaf = await iconToBase64Png(FaLeaf, "#2EC4A0", 256);
  const iconArrow = await iconToBase64Png(FaArrowRight, "#E8A838", 256);

  // ═══════════════════════════════════════════
  // SLIDE 1: Title Slide
  // ═══════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };

    // Decorative top bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.secondary }
    });

    // Subtitle line
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.8, y: 1.6, w: 0.6, h: 0.04, fill: { color: C.accent }
    });

    slide.addText("A Data-Driven Overview of Global Renewable Energy Trends", {
      x: 0.8, y: 1.0, w: 8.4, h: 0.55,
      fontSize: 14, fontFace: "Calibri", color: C.secondary, margin: 0
    });

    slide.addText("Global Renewable Energy\nin 2025", {
      x: 0.8, y: 1.8, w: 8.4, h: 1.6,
      fontSize: 44, fontFace: "Arial Black", color: C.textLight, margin: 0, lineSpacingMultiple: 1.1
    });

    slide.addText("How Far Have We Come?", {
      x: 0.8, y: 3.4, w: 8.4, h: 0.6,
      fontSize: 28, fontFace: "Calibri", color: C.accent, margin: 0, italic: true
    });

    // Source attribution
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.8, y: 4.5, w: 2.5, h: 0.01, fill: { color: "3A6B5A" }
    });

    slide.addText([
      { text: "Data: Ember (2026); Energy Institute – Statistical Review of World Energy (2025)", options: { breakLine: true, fontSize: 9 } },
      { text: "Our World in Data – Hannah Ritchie, Max Roser, Pablo Rosado", options: { fontSize: 9 } }
    ], {
      x: 0.8, y: 4.6, w: 8, h: 0.5,
      fontFace: "Calibri", color: "8FA89A", margin: 0
    });

    addFooterDark(pres, slide, 1);
  }

  // ═══════════════════════════════════════════
  // SLIDE 2: Fossil Fuel Dominance Context
  // ═══════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.lightBg };

    // Title
    slide.addText("75% of Global GHG Emissions Still Come from Fossil Fuels", {
      x: 0.5, y: 0.3, w: 9, h: 0.55,
      fontSize: 24, fontFace: "Arial Black", color: C.textDark, margin: 0
    });

    // Subtitle context
    slide.addText("Since the Industrial Revolution, fossil fuels have dominated the world's energy systems — driving climate change and harming public health.", {
      x: 0.5, y: 0.9, w: 9, h: 0.5,
      fontSize: 13, fontFace: "Calibri", color: C.textMuted, margin: 0
    });

    // Three stat cards
    const cardY = 1.65;
    const cardH = 3.0;
    const cardW = 2.8;
    const gap = 0.35;
    const startX = 0.5;

    // Card 1: 75% GHG
    slide.addShape(pres.shapes.RECTANGLE, {
      x: startX, y: cardY, w: cardW, h: cardH,
      fill: { color: C.cardBg }, shadow: makeShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: startX, y: cardY, w: cardW, h: 0.06, fill: { color: C.accentRed }
    });
    slide.addImage({ data: iconExclamation, x: startX + 0.3, y: cardY + 0.3, w: 0.45, h: 0.45 });
    slide.addText("75%", {
      x: startX + 0.3, y: cardY + 0.9, w: 2.2, h: 0.7,
      fontSize: 42, fontFace: "Arial Black", color: C.accentRed, margin: 0
    });
    slide.addText("of global greenhouse gas emissions come from burning fossil fuels for energy", {
      x: startX + 0.3, y: cardY + 1.65, w: 2.2, h: 1.1,
      fontSize: 12, fontFace: "Calibri", color: C.textDark, margin: 0
    });

    // Card 2: 5M deaths
    const c2x = startX + cardW + gap;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: c2x, y: cardY, w: cardW, h: cardH,
      fill: { color: C.cardBg }, shadow: makeShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: c2x, y: cardY, w: cardW, h: 0.06, fill: { color: C.accent }
    });
    slide.addImage({ data: iconSmog, x: c2x + 0.3, y: cardY + 0.3, w: 0.45, h: 0.45 });
    slide.addText("5M+", {
      x: c2x + 0.3, y: cardY + 0.9, w: 2.2, h: 0.7,
      fontSize: 42, fontFace: "Arial Black", color: C.accent, margin: 0
    });
    slide.addText("premature deaths per year caused by fossil fuel air pollution", {
      x: c2x + 0.3, y: cardY + 1.65, w: 2.2, h: 1.1,
      fontSize: 12, fontFace: "Calibri", color: C.textDark, margin: 0
    });

    // Card 3: Industrial Revolution
    const c3x = c2x + cardW + gap;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: c3x, y: cardY, w: cardW, h: cardH,
      fill: { color: C.cardBg }, shadow: makeShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: c3x, y: cardY, w: cardW, h: 0.06, fill: { color: C.primary }
    });
    slide.addImage({ data: iconIndustry, x: c3x + 0.3, y: cardY + 0.3, w: 0.45, h: 0.45 });
    slide.addText("Since 1850", {
      x: c3x + 0.3, y: cardY + 0.9, w: 2.2, h: 0.7,
      fontSize: 36, fontFace: "Arial Black", color: C.primary, margin: 0
    });
    slide.addText("fossil fuels have dominated most countries' energy systems, from the Industrial Revolution to today", {
      x: c3x + 0.3, y: cardY + 1.65, w: 2.2, h: 1.1,
      fontSize: 12, fontFace: "Calibri", color: C.textDark, margin: 0
    });

    addFooter(pres, slide, 2);
  }

  // ═══════════════════════════════════════════
  // SLIDE 3: Renewables in Primary Energy (~14%)
  // ═══════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.lightBg };

    slide.addText("Renewables Now Supply ~14% of Global Primary Energy", {
      x: 0.5, y: 0.3, w: 9, h: 0.55,
      fontSize: 24, fontFace: "Arial Black", color: C.textDark, margin: 0
    });

    // Left: text content
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: 1.1, w: 3.8, h: 3.8,
      fill: { color: C.cardBg }, shadow: makeShadow()
    });

    slide.addText([
      { text: "Key Points", options: { bold: true, fontSize: 16, color: C.primary, breakLine: true } },
      { text: "", options: { fontSize: 6, breakLine: true } },
      { text: "Approximately one-seventh (~14%) of the world's primary energy comes from renewable technologies (2024, substitution method).", options: { bullet: true, fontSize: 12, breakLine: true, color: C.textDark } },
      { text: "", options: { fontSize: 4, breakLine: true } },
      { text: "Primary energy encompasses electricity, transport, and heating combined.", options: { bullet: true, fontSize: 12, breakLine: true, color: C.textDark } },
      { text: "", options: { fontSize: 4, breakLine: true } },
      { text: "Transport and heating are harder to decarbonize, keeping the renewable share lower than in electricity alone.", options: { bullet: true, fontSize: 12, breakLine: true, color: C.textDark } },
      { text: "", options: { fontSize: 4, breakLine: true } },
      { text: "Countries like Norway, Brazil, and New Zealand lead; many Middle Eastern nations remain below 5%.", options: { bullet: true, fontSize: 12, color: C.textDark } },
    ], {
      x: 0.8, y: 1.3, w: 3.2, h: 3.4,
      fontFace: "Calibri", margin: 0, paraSpaceAfter: 4
    });

    // Right: map
    slide.addImage({
      path: path.join(FIGURES_DIR, "figure_2.jpg"),
      x: 4.6, y: 1.1, w: 5.0, h: 3.8,
      sizing: { type: "contain", w: 5.0, h: 3.8 }
    });

    // Caption
    slide.addText("Share of primary energy from renewables by country, 2024", {
      x: 4.6, y: 4.92, w: 5.0, h: 0.25,
      fontSize: 8, fontFace: "Calibri", color: C.textMuted, align: "center", italic: true, margin: 0
    });

    addFooter(pres, slide, 3);
  }

  // ═══════════════════════════════════════════
  // SLIDE 4: Renewable Electricity Generation Growth (bar chart)
  // ═══════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.lightBg };

    slide.addText("Renewable Electricity Generation Is Growing Rapidly", {
      x: 0.5, y: 0.3, w: 9, h: 0.55,
      fontSize: 24, fontFace: "Arial Black", color: C.textDark, margin: 0
    });

    slide.addText("Led by Wind and Solar", {
      x: 0.5, y: 0.85, w: 9, h: 0.35,
      fontSize: 15, fontFace: "Calibri", color: C.primary, italic: true, margin: 0
    });

    // Bar chart
    slide.addChart(pres.charts.BAR, [{
      name: "Generation (TWh)",
      labels: ["Hydropower", "Wind", "Solar", "Other Renewables"],
      values: [4500, 2400, 2000, 700]
    }], {
      x: 0.5, y: 1.4, w: 5.5, h: 3.4,
      barDir: "col",
