(pres.shapes.RECTANGLE, {\n      x: rightX, y: 1.35, w: 4.2, h: 0.04, fill: { color: C.secondary }\n    });\n    slide.addText(\"Leading Regions (60–98%)\", {\n      x: rightX + 0.25, y: 1.5, w: 3.7, h: 0.3,\n      fontSize: 12, fontFace: \"Arial Black\", color: C.secondary, margin: 0\n    });\n    slide.addText([\n      { text: \"Norway (~98%) — abundant hydropower\", options: { fontSize: 10, color: C.textDark, breakLine: true } },\n      { text: \"Brazil (~85%) — hydro + wind expansion\", options: { fontSize: 10, color: C.textDark, breakLine: true } },\n      { text: \"Canada (~65%) — large hydro resources\", options: { fontSize: 10, color: C.textDark, breakLine: true } },\n      { text: \"Denmark & Germany — heavy wind/solar investment\", options: { fontSize: 10, color: C.textDark } },\n    ], {\n      x: rightX + 0.25, y: 1.85, w: 3.7, h: 0.95,\n      fontFace: \"Calibri\", margin: 0, paraSpaceAfter: 2\n    });\n\n    // Laggards column\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: rightX, y: 3.1, w: 4.2, h: 1.55,\n      fill: { color: C.cardBg }, shadow: makeShadow()\n    });\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: rightX, y: 3.1, w: 4.2, h: 0.04, fill: { color: C.accentRed }\n    });\n    slide.addText(\"Lagging Regions (<10%)\", {\n      x: rightX + 0.25, y: 3.25, w: 3.7, h: 0.3,\n      fontSize: 12, fontFace: \"Arial Black\", color: C.accentRed, margin: 0\n    });\n    slide.addText([\n      { text: \"Saudi Arabia (<2%) — near-total fossil fuel dependence\", options: { fontSize: 10, color: C.textDark, breakLine: true } },\n      { text: \"South Africa (~10%) — coal-dominated grid\", options: { fontSize: 10, color: C.textDark, breakLine: true } },\n      { text: \"Much of Sub-Saharan Africa — minimal renewable infrastructure\", options: { fontSize: 10, color: C.textDark, breakLine: true } },\n      { text: \"Middle East — almost entirely fossil-fuel dependent for electricity\", options: { fontSize: 10, color: C.textDark } },\n    ], {\n      x: rightX + 0.25, y: 3.6, w: 3.7, h: 0.95,\n      fontFace: \"Calibri\", margin: 0, paraSpaceAfter: 2\n    });\n\n    addFooter(pres, slide, 8);\n  }\n\n  // ═══════════════════════════════════════════\n  // SLIDE 9: Key Takeaways\n  // ═══════════════════════════════════════════\n  {\n    const slide = pres.addSlide();\n    slide.background = { color: C.darkBg };\n\n    // Top accent bar\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent }\n    });\n\n    slide.addText(\"Key Takeaways\", {\n      x: 0.5, y: 0.25, w: 9, h: 0.5,\n      fontSize: 28, fontFace: \"Arial Black\", color: C.textLight, margin: 0\n    });\n\n    slide.addText(\"Renewables Are Growing Fast but the Transition Must Accelerate\", {\n      x: 0.5, y: 0.75, w: 9, h: 0.35,\n      fontSize: 14, fontFace: \"Calibri\", color: C.accent, italic: true, margin: 0\n    });\n\n    // 5 takeaway rows\n    const takeaways = [\n      { num: \"01\", text: \"~14% of global primary energy and ~30% of electricity now come from renewables — a milestone, but far from sufficient for climate targets.\" },\n      { num: \"02\", text: \"Hydropower remains dominant at ~50% of renewable electricity, but its growth potential is limited compared to wind and solar.\" },\n      { num: \"03\", text: \"Wind and solar are the fastest-growing energy technologies in history; combined, they now produce nearly as much electricity as hydropower.\" },\n      { num: \"04\", text: \"Stark regional disparities persist: Scandinavia and Latin America exceed 60–90% renewable electricity; much of the Middle East and Sub-Saharan Africa remain below 10%.\" },\n      { num: \"05\", text: \"Transport and heating lag far behind electricity in the renewable transition, keeping the overall primary energy share much lower.\" },\n    ];\n\n    const startY = 1.3;\n    const rowH = 0.65;\n    const rowGap = 0.12;\n\n    takeaways.forEach((item, i) => {\n      const y = startY + i * (rowH + rowGap);\n\n      // Number circle\n      slide.addShape(pres.shapes.OVAL, {\n        x: 0.5, y: y + 0.08, w: 0.45, h: 0.45,\n        fill: { color: C.primary }\n      });\n      slide.addText(item.num, {\n        x: 0.5, y: y + 0.08, w: 0.45, h: 0.45,\n        fontSize: 14, fontFace: \"Arial Black\", color: C.textLight, align: \"center\", valign: \"middle\", margin: 0\n      });\n\n      // Text\n      slide.addText(item.text, {\n        x: 1.15, y: y, w: 8.3, h: rowH,\n        fontSize: 12, fontFace: \"Calibri\", color: C.textLight, valign: \"middle\", margin: 0\n      });\n    });\n\n    // Bottom call to action\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0.5, y: 4.75, w: 9, h: 0.01, fill: { color: \"3A6B5A\" }\n    });\n    slide.addText([\n      { text: \"The world must accelerate the transition to renewables — \", options: { fontSize: 13, color: C.textLight, fontFace: \"Calibri\" } },\n      { text: \"especially in transport, heating, and regions currently left behind.\", options: { fontSize: 13, color: C.accent, fontFace: \"Calibri\", bold: true } },\n    ], {\n      x: 0.5, y: 4.85, w: 9, h: 0.4,\n      margin: 0\n    });\n\n    addFooterDark(pres, slide, 9);\n  }\n\n  // ─── Write File ───\n  await pres.writeFile({ fileName: OUTPUT_PATH });\n  console.log(\"Presentation saved to:\", OUTPUT_PATH);\n}\n\nmain().catch(err => { console.error(err); process.exit(1); });\n", "numLines": 738, "startLine": 1, "totalLines": 738}}

