35	async function iconToBase64Png(IconComponent, color, size = 256) {
36	  const svg = renderIconSvg(IconComponent, color, size);
37	  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
38	  return "image/png;base64," + pngBuffer.toString("base64");
39	}
